import com.comsol.model.*;import com.comsol.model.util.*;import java.util.*;
public class GenEnc29A04S1PhaseMesh{
 static final String ROOT="D:/Bristol course/dissertation/program work/",BASE=ROOT+"outputs/gen_enc/GEN_ENC_28_PRINT_BLIND_C/BLIND_L0900_A04_size3.mph",OUT=ROOT+"scripts/gen_enc_29_a04_s1_phase_mesh/run_output/";
 static void mesh(MeshSequence m,String mode){if(mode.equals("G1")){m.feature("size").set("custom","off");m.feature("size").set("hauto","1");return;}m.feature("size").set("custom","on");m.feature("size").set("hmax",mode.equals("F32")?.0032:.0026);m.feature("size").set("hmin",4.16e-5);m.feature("size").set("hgrad",1.3);m.feature("size").set("hcurve",.2);m.feature("size").set("hnarrow",1.0);}
 static void run(String mode)throws Exception{Model m=ModelUtil.load("m"+mode,BASE);MeshSequence q=m.component("comp1").mesh("mesh1");mesh(q,mode);q.run();try{m.result().dataset().remove("pm_ref");}catch(Exception e){}try{m.result().export().remove("pm_ref_data");}catch(Exception e){}m.result().dataset().create("pm_ref","CutPoint3D");m.result().dataset("pm_ref").set("pointx",new double[]{0});m.result().dataset("pm_ref").set("pointy",new double[]{.015});m.result().dataset("pm_ref").set("pointz",new double[]{.0046});m.result().export().create("pm_ref_data","Data");m.result().export("pm_ref_data").set("data","pm_ref");m.result().export("pm_ref_data").set("expr",new String[]{"p"});m.param().set("src_state","1");m.study("std1").feature("step1").set("plist","range(920,2,1180)");System.out.printf(Locale.US,"AUDIT %s elements=%d hmax=%s%n",mode,q.getNumElem(),q.feature("size").getString("hmax"));m.study("std1").run();m.result().export("bc_data").set("filename",OUT+mode+"_center_src1.txt");m.result().export("bc_data").run();m.result().export("pm_ref_data").set("filename",OUT+mode+"_northref_src1.txt");m.result().export("pm_ref_data").run();m.save(OUT+mode+"_src1.mph");ModelUtil.remove("m"+mode);}
 public static void main(String[] a)throws Exception{ModelUtil.initStandalone(true);run("G1");run("F32");run("F26");}
}
